# Demo7 check: noise inside solid rects vs outside. Find maximal solid rects of shape in each demo, then check per sector whether ANY noise pixel is OUTSIDE all rects (not inside any rect interior nor touching a rect edge?) 
def solid_rects(I, shp):
    H,W=len(I),len(I[0])
    seen=set(); rects=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]==shp and (r,c) not in seen:
                # grow rectangle
                q=deque([(r,c)]);seen.add((r,c));comp=set()
                while q:
                    a,b=q.popleft();comp.add((a,b))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=a+dr,b+dc
                        if 0<=nr<H and 0<=nc<W and I[nr][nc]==shp and (nr,nc) not in seen:
                            seen.add((nr,nc));q.append((nr,nc))
                rs_=min(a for a,b in comp); cs_=min(b for a,b in comp)
                rr=max(a for a,b in comp); cc=max(b for a,b in comp)
                if len(comp)==(rr-rs_+1)*(cc-cs_+1) and rr>rs_ and cc>cs_:
                    rects.append((rs_,cs_,rr,cc))
    return rects
