# Unified predicate: P = noise pixel inside a solid shape rect  OR  noise pixel not reachable from border over non-shape cells.
# Test both mappings (out==shape -> marked) on all 8 demos.
def solve(n):
    I=G[f'Demo pair {n} input']; O=G[f'Demo pair {n} output']
    cnt=Counter(v for row_ in I for v in row_)
    mc=cnt.most_common(); bgc=mc[0][0]; shp_=mc[1][0]; nzv_=mc[-1][0]
    H,W=len(I),len(I[0]); oh,ow=dims[n]
    # solid rects
    seen=set(); rects=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]==shp_ and (r,c) not in seen:
                q=deque([(r,c)]);seen.add((r,c));comp=set()
                while q:
                    a,b=q.popleft();comp.add((a,b))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=a+dr,b+dc
                        if 0<=nr<H and 0<=nc<W and I[nr][nc]==shp_ and (nr,nc) not in seen:
                            seen.add((nr,nc));q.append((nr,nc))
                a0=min(a for a,b in comp); b0=min(b for a,b in comp)
                a1=max(a for a,b in comp); b1=max(b for a,b in comp)
                if len(comp)==(a1-a0+1)*(b1-b0+1) and a1>a0 and b1>b0:
                    rects.append((a0,b0,a1,b1))
    vis=set([(0,c) for c in range(W)])|set([(H-1,c) for c in range(W)])|set([(r,0) for r in range(H)])|set([(r,W-1) for r in range(H)])
    q=deque(vis); reach=set(vis)
    while q:
        a,b=q.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=a+dr,b+dc
            if 0<=nr<H and 0<=nc<W and (nr,nc) not in reach and I[nr][nc]!=shp_:
                reach.add((nr,nc));q.append((nr,nc))
    enc={(r,c) for r in range(H) for c in range(W) if (r,c) not in reach and I[r][c]==nzv_}
    rs=[round(k*H/oh) for k in range(oh+1)]; cs=[round(k*W/ow) for k in range(ow+1)]
    res=[]
    for i in range(oh):
        row_= []
        for j in range(ow):
            Sset={(r,c) for r in range(rs[i],rs[i+1]) for c in range(cs[j],cs[j+1])}
            P = any((a0<=r<=a1 and b0<=c<=b1) and I[r][c]==nzv_ for a0,b0,a1,b1 in rects for r,c in Sset if True) or any((r,c) in enc for r,c in Sset)
            row_.append(P)
        res.append(row_)
    lab=[int(O[i][j]==shp_) for i in range(oh) for j in range(ow)]
    match=sum(res[i][j] for i in range(oh) for j in range(ow))==sum(lab)
    return match, sum(res[i][j] for i in range(oh) for j in range(ow)), lab.count(True)
