# Equivalent check: is there at least one noise pixel in the sector with NO shape neighbor (4-conn) anywhere in grid? Or within the connected component of background reachable?
def reachability(I, shp_, nzv_):
    H,W=len(I),len(I[0])
    bad={(r,c) for r in range(H) for c in range(W) if I[r][c]==shp_}
    seen=set(); q=deque()
    for r in range(H):
        for c in (0,W-1):
            if (r,c) not in bad and (r,c) not in seen: seen.add((r,c));q.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if (r,c) not in bad and (r,c) not in seen: seen.add((r,c));q.append((r,c))
    while q:
        a,b=q.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=a+dr,b+dc
            if 0<=nr<H and 0<=nc<W and (nr,nc) not in bad and (nr,nc) not in seen:
                seen.add((nr,nc));q.append((nr,nc))
    return seen
def run(n):
    I=G[f'Demo pair {n} input']; O=G[f'Demo pair {n} output']
    cnt=Counter(v for row_ in I for v in row_)
