    H,W=len(I),len(I[0]); oh,ow=dims[n]
    rs=[round(k*H/oh) for k in range(oh+1)]; cs=[round(k*W/ow) for k in range(ow+1)]
    res=[]
    for i in range(oh):
        for j in range(ow):
            Sset={(r,c) for r in range(rs[i],rs[i+1]) for c in range(cs[j],cs[j+1])}
            fr=reachability(I,shp_,nzv_)
            enc=[(r,c) for r,c in Sset if I[r][c]==nzv_ and (r,c) not in fr]
            exp = nzv_ if enc else bgc
            res.append(exp==O[i][j])
    ok=sum(res)
    return ok,len(res),res
