                    if (r0,c0) in ysset and (r0,c0+1) in ysset and (r0+1,c0) in ysset and (r0+1,c0+1) in ysset:
                        hasrect=True; break
                if hasrect: break
            tgt=(O[i][j]==Xc)
            res[(tgt==not hasrect)]+=1
    okA=res.get(True,0); okB=res.get(False,0)
    tot=oh*ow
    print(n,'out==notHasRect:',collections.Counter({True:okA,False:okB}),'/total',tot)

import os,re,collections,itertools
from collections import Counter,defaultdict,deque
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
dims={n:(len(G[f'Demo pair {n} output']),len(G[f'Demo pair {n} output'][0])) for n in range(1,9)}
for n in range(1,9):
    I=G[f'Demo pair {n} input']; O=G[f'Demo pair {n} output']
    colcnt=Counter(v for row in I for v in row)
    oh,ow=dims[n]; H,W=len(I),len(I[0])
    R=[k*H//oh for k in range(oh+1)]; C=[k*W//ow for k in range(ow+1)]
    bgc=colcnt.most_common(1)[0][0]
    rem=[c for c,v in colcnt.items() if c!=bgc]
    outs=set(v for row in O for v in row)
    Xc=[c for c in rem if c in outs][0]
    Yc=[c for c in rem if c!=Xc][0]
    ysset={(r,c) for r in range(H) for c in range(W) if I[r][c]==Yc}
    res=collections.Counter()
    for i in range(oh):
        for j in range(ow):
            hasrect=False
            lim=min(R[i+1]-1,C[j+1]-1)
            for r0 in range(R[i],lim+1):
                for c0 in range(C[j],lim+1):
                    if (r0,c0) in ysset and (r0,c0+1) in ysset and (r0+1,c0) in ysset and (r0+1,c0+1) in ysset:
                        hasrect=True; break
                if hasrect: break
            tgt=(O[i][j]==Xc)
            key = True if (tgt != hasrect) else False   # out==noise iff no 2x2 rect of shape color
            res[key]+=1
    okA=res.get(True,0); okB=res.get(False,0)
    print(n,'out==notHasRect:',okA,'/',okA+okB)
